insert into tap_results select lives_ok($$select public.agri_command('refund_sale',pg_temp.ctx()||jsonb_build_object('saleId',pg_temp.i(701),'refundId',pg_temp.i(801),'shiftId',(select id from public.cashier_shifts where closed_at is null),'reason','Full cash return','returns','[{"lineIndex":0,"quantity":"0.5","disposition":"resalable"}]'::jsonb))$$,'Refund response retry cannot refund twice');
